		"size": p.Size,
		"variant": p.Variant,
	}, p.Class)
}

// Dialog renders the Dialog contract.
templ Dialog(p DialogProps) {
	<dialog
		class={ DialogClasses(p) }
		open?={ p.Open }
		if uiutils.IsSetStr(p.ID) {
			id={ p.ID }
		}
		if uiutils.IsSetStr(p.DataUI8Kit) {
			data-ui8kit={ p.DataUI8Kit }
		}
		if uiutils.IsSetStr(p.AriaLabel) {
			aria-label={ p.AriaLabel }
		}
		if uiutils.IsSetStr(p.AriaLabelledBy) {
			aria-labelledby={ p.AriaLabelledBy }
		}
		if uiutils.IsSetStr(p.AriaDescribedBy) {
			aria-describedby={ p.AriaDescribedBy }
		}
		{ p.Attrs... }
	>
		{ children... }
	</dialog>
}

